INSERT INTO public.glossary_terms
  ("id", "term", "aliases", "definition", "learnMoreUrl", "isActive", "createdAt", "updatedAt")
VALUES
  ('cb6a0caeb3980aa17156f8d4a', 'Algorithmic collusion', ARRAY[]::text[], 'A situation in which pricing algorithms facilitate or sustain coordination between competing firms, potentially raising prices above competitive levels. It may involve explicit agreements or tacit coordination.', 'https://www.gov.uk/government/publications/algorithms-how-they-can-reduce-competition-and-harm-consumers/algorithms-how-they-can-reduce-competition-and-harm-consumers', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cb2bc7805344f6b411c8d8d68', 'Algorithmic pricing', ARRAY['pricing algorithm']::text[], 'The use of software to recommend, set or adjust prices using information such as demand, market conditions or rivals'' prices. Using an algorithm does not in itself mean firms are colluding.', 'https://competitionandmarkets.blog.gov.uk/2024/11/08/pricing-algorithms-and-competition-law-what-you-need-to-know/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c4b016dc9df160683a22938c5', 'Antitrust law', ARRAY['competition law']::text[], 'Laws and enforcement rules intended to protect competition by restricting practices such as cartels and certain anticompetitive mergers or abuses of market power.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c2596144e249d7ce970983313', 'Barriers to entry', ARRAY[]::text[], 'Obstacles that make it costly or difficult for new firms to enter a market, such as high start-up costs, regulation, patents or advantages held by incumbents.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cba4f47d21eb7747decf3397f', 'Best response', ARRAY[]::text[], 'In game theory, a strategy that gives a player the highest available payoff for the strategies chosen by the other players.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cbc3a8adbd472bdde1bccde12', 'Bundling', ARRAY[]::text[], 'Selling two or more goods or services together as a package, sometimes instead of making each available separately. It can benefit consumers but may also affect competition.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c0bbeb13849840a7878cb42d3', 'Cartel', ARRAY[]::text[], 'A group of competing businesses that coordinate commercially sensitive decisions, typically prices, output or market allocation, instead of competing independently.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c98b931bb30d658d8ab0e8ce9', 'Collusion', ARRAY[]::text[], 'When competing firms coordinate decisions, such as prices or output, rather than competing independently. Coordination can be explicit or tacit and may lead to higher prices or reduced competition.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c51022ca02c8aff5ce9395d44', 'Coordination game', ARRAY[]::text[], 'A game in which players benefit from choosing mutually compatible strategies and may face more than one possible equilibrium.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c3ac3c3e6e08b033cb0a6fa1a', 'Duopoly', ARRAY[]::text[], 'A market dominated by two major sellers. Each firm''s pricing and output decisions can materially affect the other, making their strategic interaction important.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c133520a38abc214941f57def', 'Dynamic pricing', ARRAY[]::text[], 'A pricing approach in which a seller changes prices over time in response to factors such as demand, capacity or market conditions. It can be implemented manually or using algorithms.', 'https://competitionandmarkets.blog.gov.uk/2024/11/08/pricing-algorithms-and-competition-law-what-you-need-to-know/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cca9b3744ac00953815547b92', 'Exclusive dealing', ARRAY[]::text[], 'An arrangement requiring a retailer or distributor to deal only, or mainly, with a particular supplier. Depending on the market, it can restrict competitors'' access to customers.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c175ca1af2c6fff873d5405b9', 'Herfindahl-Hirschman index', ARRAY['HHI']::text[], 'A measure of market concentration calculated by adding the squared market shares of all firms in a market. Higher values indicate greater concentration.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c2790f5cd3833e17f0a53c225', 'Market share', ARRAY[]::text[], 'A firm''s sales as a proportion of total sales in a defined market, usually expressed as a percentage. It is one indicator of competitive position.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c2a14858f10040ccb8d589c70', 'Market structure', ARRAY[]::text[], 'The organisation of a market, including how many firms compete, how concentrated sales are, how differentiated products are and how easily new firms can enter.', 'https://openstax.org/books/principles-economics-3e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c272a75c333cacdc2e485e52a', 'Monopolistic competition', ARRAY[]::text[], 'A market structure with many firms selling differentiated products, where each has some pricing power but faces competition from close substitutes.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c7b1714d3f588a8d5c9a6034e', 'Natural monopoly', ARRAY[]::text[], 'A market where one provider can supply the relevant output at lower total cost than multiple competing providers, often because of substantial fixed costs and economies of scale.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cc91e700cc30b97e0007e883c', 'Perfect Bayesian equilibrium', ARRAY['PBE']::text[], 'An equilibrium concept for games with incomplete information in which players'' strategies are optimal given their beliefs, and beliefs are updated consistently with observed actions where possible.', 'https://ocw.mit.edu/courses/14.126-game-theory-spring-2024/mit14_126_s24_lecture_3_signaling.pdf', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c09724064e7f661c79766c0f0', 'Pooling equilibrium', ARRAY[]::text[], 'In a signalling game, an equilibrium where different privately informed types choose the same observable action. The action therefore does not reveal which type a participant is.', 'https://ocw.mit.edu/courses/14.126-game-theory-spring-2024/mit14_126_s24_lecture_3_signaling.pdf', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c215671c3e729e484bd086d2a', 'Predatory pricing', ARRAY[]::text[], 'A strategy in which a firm prices aggressively, potentially below an appropriate measure of cost, to drive out or deter competitors and later recover losses through greater market power.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c4a10103616a0fbc2b6d7f2fa', 'Price discrimination', ARRAY[]::text[], 'Charging different prices to different customers or groups for the same or similar product when the differences are not explained solely by costs. The practice is not automatically unlawful.', 'https://www.gov.uk/government/publications/algorithms-how-they-can-reduce-competition-and-harm-consumers/algorithms-how-they-can-reduce-competition-and-harm-consumers', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c70ec67831b07b4a7d459d870', 'Price fixing', ARRAY[]::text[], 'An agreement or concerted practice between competitors to set, maintain or coordinate prices rather than determine them independently.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c7ddb71e5b692cf636ca5a2a9', 'Price taker', ARRAY[]::text[], 'A buyer or seller whose individual decisions cannot materially affect the market price, so it treats that price as given.', 'https://openstax.org/books/principles-economics-3e/pages/8-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c063fb190106821935cca2154', 'Principal-agent problem', ARRAY['principal-agent relationship']::text[], 'A difficulty that arises when one person or organisation acts for another but their interests differ and the principal cannot fully observe or control the agent''s behaviour.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c9c62c51ee37c63e415ddf000', 'Prisoner''s dilemma', ARRAY['prisoners dilemma']::text[], 'A game where each player has an incentive to choose a strategy that leaves both worse off than if they had cooperated, illustrating the tension between individual incentives and collective outcomes.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('ceeddd17dc583a74941e955ac', 'Product differentiation', ARRAY[]::text[], 'Differences in features, quality, branding or other characteristics that make consumers view one firm''s product as distinct from rivals'' products.', 'https://openstax.org/books/principles-economics-3e/pages/10-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c7a02f2360ffe5eb4e3b6f345', 'Regulatory capture', ARRAY[]::text[], 'A situation in which regulation or its enforcement comes to serve the interests of regulated businesses rather than the wider public.', 'https://openstax.org/books/principles-economics-3e/pages/11-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c7f78833762954a716ed58fba', 'Repeated game', ARRAY[]::text[], 'A strategic interaction played more than once, allowing participants to react to previous behaviour and potentially sustain cooperation through future rewards or punishments.', 'https://www.core-econ.org/glossary/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('c272991c02a647204dae3f87d', 'Semi-separating equilibrium', ARRAY[]::text[], 'In a signalling game, an equilibrium in which different types'' actions partially overlap, so observed behaviour reveals some but not complete information about type.', 'https://ocw.mit.edu/courses/14.126-game-theory-spring-2024/mit14_126_s24_lecture_3_signaling.pdf', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('ca94e2b57c000fd15e6de1534', 'Separating equilibrium', ARRAY[]::text[], 'In a signalling game, an equilibrium where different privately informed types choose distinct observable actions, allowing an observer to infer the participant''s type.', 'https://ocw.mit.edu/courses/14.126-game-theory-spring-2024/mit14_126_s24_lecture_3_signaling.pdf', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cf168e81d468b03f0ba4fe508', 'Signalling game', ARRAY['signaling game']::text[], 'A strategic interaction where one player knows information about their own type, takes an observable action, and another player responds after drawing inferences from that action.', 'https://ocw.mit.edu/courses/14.126-game-theory-spring-2024/mit14_126_s24_lecture_3_signaling.pdf', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cbdb6f07e5daf445b63677b3e', 'Tacit collusion', ARRAY[]::text[], 'Coordination between competitors that produces a less competitive outcome without an explicit agreement. Firms may independently recognise that avoiding price cuts is mutually profitable.', 'https://www.gov.uk/government/publications/algorithms-how-they-can-reduce-competition-and-harm-consumers/algorithms-how-they-can-reduce-competition-and-harm-consumers', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc'))
